import networkx as nx

def solve():
    # Vertices 0-11
    # A = {0, 1, 2, 3, 4, 5}, B = {6, 7, 8, 9, 10, 11}
    A = [0, 1, 2, 3, 4, 5]
    B = [6, 7, 8, 9, 10, 11]

    fixed_edges = [(2,8), (1,9), (0,6), (3,10), (0,9), (3,9)]

    # Create a bipartite graph
    G = nx.Graph()
    G.add_nodes_from(range(12))
    G.add_edges_from(fixed_edges)

    # Check if it's bipartite
    if not nx.is_bipartite(G):
        return None

    # We need to add edges to make min degree 4
    # Try to add edges greedily
    for u in A:
        for v in B:
            if G.degree(u) < 4 or G.degree(v) < 4:
                if not G.has_edge(u, v):
                    G.add_edge(u, v)

    # Check if all degrees are at least 4
    for i in range(12):
        if G.degree(i) < 4:
            return None

    return list(G.edges())

result = solve()
print(result)
